package com.ilp.marks;

import java.util.*;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

// WebController.java: builds the page from your steps. Students do NOT edit this file.
@RestController
public class WebController {
    static final List<Student> students = new ArrayList<>(); // every student added, in order
    static final String HTML = "text/html;charset=UTF-8";

    @GetMapping(value = "/", produces = HTML)
    public String home() {
        String form = "<form method=\"post\" action=\"/add\">" + Ui.part(2, Step02NameBox::nameBox)
            + Ui.part(3, Step03MarksBox::marksBox) + Ui.part(4, Step04AddButton::addButton) + "</form>";

        String list;
        if (students.isEmpty()) {
            list = "<p style=\"color:#6b7480\">No students yet. Add one above.</p>";
        } else if (!Checks.done(5)) {
            list = Ui.box(5) + "<p style=\"color:#6b7480\">(" + students.size() + " student(s) saved, but not shown yet)</p>";
        } else {
            StringBuilder rows = new StringBuilder("<ul>");
            for (int i = 0; i < students.size(); i++) {
                Student s = students.get(i);
                Student safe = new Student(Ui.esc(s.name), s.marks);
                String row = Ui.part(5, () -> Step05ShowList.studentRow(safe));
                String extra = "";
                if (Checks.done(7)) extra += "<span class=\"badge\">Grade " + Step07Grade.grade(s.marks) + "</span>";
                if (Checks.done(9)) extra += "<a class=\"del\" href=\"/delete/" + i + "\" title=\"Delete\">❌</a>";
                rows.append(row.contains("</li>") ? row.replace("</li>", extra + "</li>") : row + extra);
            }
            list = rows + "</ul>" + (Checks.done(7) ? "" : Ui.box(7)) + (Checks.done(9) ? "" : Ui.box(9));
        }

        String stats;
        if (Checks.done(6) && !students.isEmpty()) {
            int total = Step06Total.totalMarks(students);
            stats = "<div class=\"stats\"><div class=\"stat\">Total<b>" + total + "</b></div><div class=\"stat\">Average<b>"
                + String.format("%.1f", total * 1.0 / students.size()) + "</b></div></div>";
        } else if (Checks.done(6)) {
            stats = "<p style=\"color:#6b7480\">Total and average appear after you add students.</p>";
        } else stats = Ui.box(6);

        String top = "";
        if (Checks.done(8) && !students.isEmpty()) {
            Student t = Step08Topper.topper(students);
            top = "<h2>🏆 Topper: " + Ui.esc(t.name) + " (" + t.marks + ")</h2>";
        } else if (!Checks.done(8)) top = Ui.box(8);

        String inner = "<div class=\"card\">" + Ui.part(1, Step01Header::header) + form + "</div>"
            + "<div class=\"card\"><h2>Students</h2>" + list + "</div>"
            + "<div class=\"card\">" + stats + top + "</div>"
            + Ui.part(10, Step10Footer::footer);
        return Ui.page(inner);
    }

    @PostMapping("/add")
    public ResponseEntity<Void> add(@RequestParam(defaultValue = "") String name, @RequestParam(defaultValue = "0") String marks) {
        String n = name.trim().isEmpty() ? "Student " + (students.size() + 1) : name.trim();
        int m;
        try { m = Integer.parseInt(marks.trim()); } catch (NumberFormatException e) { m = 0; }
        students.add(new Student(n, m));
        return home302();
    }

    @GetMapping("/delete/{i}")
    public ResponseEntity<Void> delete(@PathVariable int i) {
        if (Checks.done(9) && i >= 0 && i < students.size()) Step09Delete.deleteStudent(students, i);
        return home302();
    }

    // ==============================================================
    //  API (CRUD): ready-made. Call it with curl: commands/08_api_crud.txt
    //  Create = POST · Read = GET · Update = PUT · Delete = DELETE
    //  (Java keeps data in memory. SQL for each call is in the comments.)
    // ==============================================================
    @GetMapping("/api/students")                         // READ    SELECT * FROM students
    public List<Map<String, Object>> apiList() {
        List<Map<String, Object>> out = new ArrayList<>();
        for (int i = 0; i < students.size(); i++) out.add(Map.of("id", i, "name", students.get(i).name, "marks", students.get(i).marks));
        return out;
    }

    @PostMapping("/api/students")                        // CREATE  INSERT INTO students ...
    public ResponseEntity<Object> apiCreate(@RequestBody Map<String, Object> body) {
        String name = String.valueOf(body.getOrDefault("name", "")).trim();
        Integer marks = toInt(body.get("marks"));
        if (name.isEmpty()) return ResponseEntity.status(400).body(Map.of("error", "name is required"));
        if (marks == null) return ResponseEntity.status(400).body(Map.of("error", "marks must be a number"));
        students.add(new Student(name, marks));
        return ResponseEntity.status(201).body(Map.of("id", students.size() - 1, "name", name, "marks", marks));
    }

    @PutMapping("/api/students/{i}")                     // UPDATE  UPDATE students SET marks = ...
    public ResponseEntity<Object> apiUpdate(@PathVariable int i, @RequestBody Map<String, Object> body) {
        if (i < 0 || i >= students.size()) return ResponseEntity.status(404).body(Map.of("error", "student not found"));
        Integer marks = toInt(body.get("marks"));
        if (marks == null) return ResponseEntity.status(400).body(Map.of("error", "marks must be a number"));
        students.get(i).marks = marks;
        return ResponseEntity.ok(Map.of("id", i, "name", students.get(i).name, "marks", marks));
    }

    @DeleteMapping("/api/students/{i}")                  // DELETE  DELETE FROM students WHERE id = ...
    public ResponseEntity<Object> apiDelete(@PathVariable int i) {
        if (i < 0 || i >= students.size()) return ResponseEntity.status(404).body(Map.of("error", "student not found"));
        Student gone = students.remove(i);
        return ResponseEntity.ok(Map.of("deleted", gone.name));
    }

    static Integer toInt(Object o) {
        try { return o == null ? null : (int) Double.parseDouble(String.valueOf(o)); } catch (NumberFormatException e) { return null; }
    }

    static ResponseEntity<Void> home302() {
        return ResponseEntity.status(302).header("Location", "/").build();
    }
}
